    p.add_argument("--by", choices=["category", "month"], default="category")
    p.add_argument("--json", action="store_true", help="print JSON")

    def filters(p):
        p.add_argument(
            "--category",
            metavar="C",
            help="only this category (a value starting with a dash also works: --category=-x)",
        )
        p.add_argument("--since", metavar="DATE", type=_date_arg)
        p.add_argument("--until", metavar="DATE", type=_date_arg)

    p = sub.add_parser("list", help="print entries, oldest first")
    file_arg(p)
    filters(p)
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("add", help="append an entry to the ledger file")
    p.add_argument("file", metavar="FILE")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")

    p = sub.add_parser("export", help="print entries as CSV")
    file_arg(p)
    p.add_argument("--format", choices=["csv"], default="csv")
    return parser


def _load(path):
    """Read and parse a ledger; returns entries."""
    shown = "<stdin>" if path == "-" else path
    try:
        if path == "-":
            raw = getattr(sys.stdin, "buffer", None)
            if raw is not None:
                text = raw.read().decode("utf-8-sig")
            else:
                text = sys.stdin.read()  # already-decoded text; parse() drops a BOM
        else:
            with open(path, encoding="utf-8-sig") as fh:
                text = fh.read()
    except (OSError, UnicodeDecodeError) as exc:
        reason = exc.strerror if isinstance(exc, OSError) and exc.strerror else exc
        raise _Fail(2, "%s: cannot read %s: %s" % (PROG, shown, reason))
    try:
        return parse(text)
    except ParseError as exc:
        raise _Fail(1, "%s: %s: %s" % (PROG, shown, exc))


def _sorted(entries):
    return sorted(entries, key=lambda e: e.date)  # stable


def _cmd_balance(args):
    total = balance(_load(args.file))
    if args.json:
        return json.dumps({"balance": money(total)})
    return money(total)


def _cmd_summary(args):
    entries = _load(args.file)
    totals = by_month(entries) if args.by == "month" else by_category(entries)
    if args.json:
        return json.dumps({k: money(v) for k, v in totals.items()})
    return "\n".join("%s  %s" % (k, money(v)) for k, v in totals.items())


def _cmd_list(args):
    entries = _sorted(
        filter_entries(
            _load(args.file),
            category=args.category,
            since=args.since,
            until=args.until,
        )
    )
    if args.json:
        return json.dumps(
            [
                {
                    "date": e.date.isoformat(),
                    "category": e.category,
                    "amount": money(e.amount),
                    "note": e.note,
                }
                for e in entries
            ]
        )
    return "\n".join(format_entry(e) for e in entries)


def _cmd_export(args):
    out = io.StringIO()
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in _sorted(_load(args.file)):
        writer.writerow([e.date.isoformat(), e.category, money(e.amount), e.note])
    return out.getvalue().rstrip("\n")


def _one_line(text):
    return "\r" not in text and "\n" not in text


def _build_entry(args):
    """Validate the `add` arguments with the ledger rules; returns an Entry."""
    try:
        date = parse_date(args.date)
        category = args.category
        if len(category.split()) != 1 or category != category.strip():
            raise ValueError(
                "invalid category %r (must be one word without spaces)" % category
            )
        amount = parse_amount(args.amount)
        note = args.note.strip()
        if not _one_line(note):
            raise ValueError("note must not contain a line break")
    except ValueError as exc:
        raise _Fail(1, "%s: invalid entry: %s" % (PROG, exc))
    return Entry(date, category.lower(), amount, note)


def _cmd_add(args):
    if args.file == "-":
        raise _Fail(2, "%s: add does not accept '-' as FILE" % PROG)
    entry = _build_entry(args)
    line = format_entry(entry)
    try:
        prefix = b""
        if os.path.exists(args.file) and os.path.getsize(args.file) > 0:
            with open(args.file, "rb") as fh:
                fh.seek(-1, os.SEEK_END)
                if fh.read(1) != b"\n":
                    prefix = b"\n"
        with open(args.file, "ab") as fh:
            fh.write(prefix + (line + "\n").encode("utf-8"))
    except OSError as exc:
        raise _Fail(2, "%s: cannot write %s: %s" % (PROG, args.file, exc.strerror or exc))
    return line


_COMMANDS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "add": _cmd_add,
    "export": _cmd_export,
}


def _silence_stdout():
    """Point fd 1 at devnull so the flush at interpreter exit cannot fail again."""
    try:
        fd = os.open(os.devnull, os.O_WRONLY)
        try:
            os.dup2(fd, sys.stdout.fileno())
        finally:
            os.close(fd)
    except (OSError, ValueError, AttributeError):
        pass  # stdout has no real descriptor (e.g. replaced in-process)


def _emit(text):
    """Write the result to stdout; returns the exit status.

    A reader that closes early (``| head -1``) is not an error: quiet exit 0.
    Any other failure to write is one line on stderr and exit 2.
    """
    if sys.stdout is None:
        print("%s: cannot write output: standard output is closed" % PROG, file=sys.stderr)
        return 2
    try:
        raw = getattr(sys.stdout, "buffer", None)
        if raw is not None:
            sys.stdout.flush()
            raw.write(text.encode("utf-8"))  # UTF-8 whatever the locale says
            raw.flush()
        else:
            sys.stdout.write(text)  # text-only stand-in (e.g. StringIO)
            sys.stdout.flush()
    except BrokenPipeError:
        _silence_stdout()
        return 0
    except OSError as exc:
        _silence_stdout()
        print("%s: cannot write output: %s" % (PROG, exc.strerror or exc), file=sys.stderr)
        return 2
    return 0


def _prepare(argv):
    """Rewrite argv so dash-prefixed free text reaches the right place.

    After ``add`` every argument is positional (except -h/--help); ``list
    --category -x`` becomes ``--category=-x``.
    """
    argv = list(sys.argv[1:] if argv is None else argv)
    if argv and argv[0] == "add":
        rest = argv[1:]
        if rest and rest[0] != "--" and not any(a in _HELP for a in rest):
            return ["add", "--"] + rest
    elif argv and argv[0] == "list":
        out = []
        i = 0
        while i < len(argv):
            arg = argv[i]
            if arg == "--":
                out.extend(argv[i:])
                break
            nxt = argv[i + 1] if i + 1 < len(argv) else None
            if (
                arg == "--category"
                and nxt is not None
                and nxt.startswith("-")
                and nxt not in _LIST_OPTIONS
            ):
                out.append("%s=%s" % (arg, nxt))
                i += 2
                continue
            out.append(arg)
            i += 1
        return out
    return argv


def main(argv=None):
    args = _build_parser().parse_args(_prepare(argv))
    try:
        output = _COMMANDS[args.command](args)
    except _Fail as fail:
        print(fail.message, file=sys.stderr)
        return fail.status
    if output:
        return _emit(output + "\n")
    return 0
